#!/bin/sh
hash=$(cat "$0" patches/*.patch | git hash-object --stdin) && echo $hash | cmp -s - build/hash || { r=https://ghcr.io/v2/exactly/maestro && t=$(curl -fsSm 10 'https://ghcr.io/token?scope=repository:exactly/maestro:pull') && a="Authorization: Bearer $(node -p 'JSON.parse(process.argv[1]).token' "$t")" && m=$(curl -fsSm 10 -H "$a" -H 'Accept: application/vnd.oci.image.manifest.v1+json' $r/manifests/$hash) && rm -rf build && mkdir build && curl -fsSL --connect-timeout 10 -Y 1000000 -y 10 -H "$a" $r/blobs/$(node -p 'JSON.parse(process.argv[1]).layers[0].digest' "$m") | tar -xzf - -C build && echo $hash > build/hash; } || { src=$(mktemp -d) && trap 'rm -rf $src' EXIT && git init -q $src && git -C $src fetch -q --depth 1 https://github.com/mobile-dev-inc/Maestro cli-2.12.1 && git -C $src checkout -q FETCH_HEAD && git -C $src apply $PWD/patches/*.patch && $src/gradlew -p $src :maestro-cli:installDist -x :maestro-ios-driver:buildIosDriver && rm -rf build && mv $src/maestro-cli/build/install/maestro build && echo $hash > build/hash; }
